/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Code Block" (boardui.com/components/line-chart-card).
 * No BoardUI source was used.
 */
"use client";

import { RiFileCodeLine, RiTextWrap } from "@remixicon/react";
import { useMemo, useState } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";

import { cx } from "@/lib/cx";
import { CopyButton } from "@/components/motion/code-block-copy";
import { TOKEN_CLASS, splitLines, tokenizeTsx } from "@/components/motion/code-block-tokenize";
import type { Token } from "@/components/motion/code-block-tokenize";

export type CodeBlockLanguage = "tsx" | "plain";
export type CodeBlockChipTone = "neutral" | "file";

export interface CodeBlockProps {
  /** The source to show and copy. Leading and trailing blank lines are trimmed. */
  code: string;
  /** Label in the header chip: a filename (`line-chart-card.tsx`) or a role (`usage`). */
  filename?: string;
  /** `neutral` is the plain white chip; `file` is the purple file chip with a code glyph. */
  chipTone?: CodeBlockChipTone;
  /** `tsx` runs the built-in tokenizer; `plain` prints the text as is. */
  language?: CodeBlockLanguage;
  /** Gutter with 1-based line numbers (not selectable, not copied). */
  showLineNumbers?: boolean;
  /** 1-based line numbers to tint. */
  highlightLines?: number[];
  /** Soft-wrap long lines (controlled). */
  wrap?: boolean;
  /** Initial soft-wrap state when uncontrolled. */
  defaultWrap?: boolean;
  onWrapChange?: (wrap: boolean) => void;
  /** Hide the wrap toggle in the header. */
  hideWrapToggle?: boolean;
  /** Hide the copy button in the header. */
  hideCopy?: boolean;
  /** Cap the code panel height (px); it scrolls past this. */
  maxHeight?: number;
  /** Extra controls rendered in the header before wrap/copy. */
  actions?: ReactNode;
  onCopied?: (code: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

function trimBlankEdges(code: string) {
  return code.replace(/^(?:[ \t]*\n)+/, "").replace(/\s+$/, "");
}

function plainTokens(code: string): Token[] {
  return [{ kind: "plain", text: code }];
}

/**
 * A docs code block: filename chip header with wrap and copy actions over a
 * white, inset code panel. TSX is coloured by a ~200 line tokenizer that ships
 * alongside (no highlighter dependency); everything else renders verbatim.
 */
export function CodeBlock({
  code,
  filename,
  chipTone = "neutral",
  language = "tsx",
  showLineNumbers = true,
  highlightLines,
  wrap: controlledWrap,
  defaultWrap = false,
  onWrapChange,
  hideWrapToggle = false,
  hideCopy = false,
  maxHeight,
  actions,
  onCopied,
  className,
  ref,
}: CodeBlockProps) {
  const [uncontrolledWrap, setUncontrolledWrap] = useState(defaultWrap);
  const wrap = controlledWrap ?? uncontrolledWrap;
  const setWrap = (next: boolean) => {
    setUncontrolledWrap(next);
    onWrapChange?.(next);
  };

  const source = useMemo(() => trimBlankEdges(code), [code]);

  // #region critical
  // Tokenize once per source, then cut into rows so each line owns its gutter
  // cell. The gutter is sticky, so numbers stay put while long lines scroll.
  const lines = useMemo(
    () => splitLines(language === "tsx" ? tokenizeTsx(source) : plainTokens(source)),
    [source, language],
  );
  const highlighted = useMemo(() => new Set(highlightLines ?? []), [highlightLines]);
  const gutterCh = String(lines.length).length;

  const rows = lines.map((tokens, index) => {
    const lineNo = index + 1;
    const isHighlighted = highlighted.has(lineNo);
    return (
      <span
        key={lineNo}
        data-line={lineNo}
        data-highlighted={isHighlighted || undefined}
        className={cx("flex min-h-5", isHighlighted && "bg-background-secondary-default")}
      >
        {showLineNumbers && (
          <span
            aria-hidden
            className={cx(
              "sticky start-0 z-10 shrink-0 select-none ps-4 pe-4 text-end text-text-tertiary",
              isHighlighted ? "bg-background-secondary-default" : "bg-docs-code-background",
            )}
            style={{ width: `calc(${gutterCh}ch + 2rem)` }}
          >
            {lineNo}
          </span>
        )}
        <span
          className={cx(
            "min-w-0 flex-1 pe-5",
            !showLineNumbers && "ps-5",
            wrap ? "whitespace-pre-wrap break-words" : "whitespace-pre",
          )}
        >
          {tokens.map((token, t) => (
            <span key={t} className={TOKEN_CLASS[token.kind]}>
              {token.text}
            </span>
          ))}
          {"\n"}
        </span>
      </span>
    );
  });
  // #endregion

  const panelStyle: CSSProperties | undefined = maxHeight ? { maxHeight } : undefined;
  const hasHeader = Boolean(filename || actions || !hideCopy || !hideWrapToggle);

  return (
    <figure
      ref={ref}
      className={cx("flex w-full min-w-0 flex-col rounded-2xl bg-background-secondary-default p-1.5", className)}
    >
      {hasHeader && (
        <figcaption className="flex min-h-9 items-center justify-between gap-2 ps-0.5 pe-0.5 pb-1.5">
          {filename ? (
            chipTone === "file" ? (
              <span className="inline-flex min-w-0 items-center gap-1.5 rounded-lg border border-docs-file-chip-border bg-docs-file-chip-background px-2 py-0.5 font-mono text-body-2-medium text-docs-file-chip-foreground">
                <RiFileCodeLine aria-hidden className="size-3.5 shrink-0" />
                <span className="truncate">{filename}</span>
              </span>
            ) : (
              <span className="inline-flex min-w-0 items-center rounded-lg bg-background-primary-default px-2.5 py-1 text-body-medium text-text-primary shadow-2xs">
                <span className="truncate">{filename}</span>
              </span>
            )
          ) : (
            <span />
          )}
          <span className="flex shrink-0 items-center gap-0.5">
            {actions}
            {!hideWrapToggle && (
              <button
                type="button"
                aria-label="Wrap lines"
                aria-pressed={wrap}
                onClick={() => setWrap(!wrap)}
                className={cx(
                  "inline-flex size-8 cursor-pointer items-center justify-center rounded-lg transition-colors duration-150 ease-out",
                  "outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                  wrap
                    ? "bg-background-primary-default text-foreground-icon-primary shadow-2xs"
                    : "text-foreground-icon-secondary hover:bg-background-secondary-hover hover:text-foreground-icon-primary",
                )}
              >
                <RiTextWrap aria-hidden className="size-[18px]" />
              </button>
            )}
            {!hideCopy && <CopyButton value={source} onCopied={onCopied} />}
          </span>
        </figcaption>
      )}
      <div className="overflow-hidden rounded-xl bg-docs-code-background shadow-xs">
        <pre
          tabIndex={0}
          aria-label={filename ? `${filename} source` : "Code"}
          style={panelStyle}
          className="overflow-auto py-4 font-mono text-body-regular outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-inset"
        >
          <code className={cx("flex flex-col", wrap ? "w-full" : "w-max min-w-full")}>{rows}</code>
        </pre>
      </div>
    </figure>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Code Block" (boardui.com/components/line-chart-card).
 * No BoardUI source was used.
 */

/**
 * A deliberately small TSX tokenizer for docs snippets. It is not a parser:
 * it reads left to right with one sticky regex per step and a tiny mode stack
 * (code / JSX tag / JSX text), which is enough to colour keywords, strings,
 * comments, numbers, function calls, JSX tag names and attribute names in the
 * kind of 5–60 line examples a docs page shows. No dependency, no WASM, no
 * grammar files.
 */

export type TokenKind =
  | "plain"
  | "comment"
  | "keyword"
  | "string"
  | "number"
  | "function"
  | "tag"
  | "attr"
  | "punct";

export interface Token {
  kind: TokenKind;
  text: string;
}

/** Tailwind classes per token kind. Every colour is a kit token that flips in dark mode. */
export const TOKEN_CLASS: Record<TokenKind, string> = {
  plain: "text-text-primary",
  comment: "text-text-secondary",
  keyword: "text-status-purple-text",
  string: "text-status-orange-text",
  number: "text-calendar-event-pink-time",
  function: "text-calendar-event-blue-title",
  tag: "text-calendar-event-emerald-time",
  attr: "text-status-cyan-text",
  punct: "text-text-secondary",
};

const KEYWORDS = new Set([
  "as", "async", "await", "break", "case", "catch", "class", "const", "continue",
  "default", "delete", "do", "else", "enum", "export", "extends", "for", "from",
  "function", "if", "implements", "import", "in", "instanceof", "interface", "let",
  "new", "of", "readonly", "return", "satisfies", "static", "switch", "this",
  "throw", "try", "type", "typeof", "var", "void", "while", "yield", "keyof",
]);

/** Literals read as values, so they share the number colour. */
const LITERALS = new Set(["true", "false", "null", "undefined", "NaN", "Infinity"]);

type Mode =
  | { kind: "code"; braces: number }
  | { kind: "tag"; closing: boolean }
  | { kind: "text" };

const RE = {
  space: /\s+/y,
  lineComment: /\/\/[^\n]*/y,
  blockComment: /\/\*[\s\S]*?(?:\*\/|$)/y,
  string: /"(?:\\.|[^"\\\n])*"?|'(?:\\.|[^'\\\n])*'?|`(?:\\[\s\S]|[^`\\])*`?/y,
  number: /(?:0[xX][\da-fA-F_]+|\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?n?)/y,
  ident: /[A-Za-z_$][\w$]*/y,
  tagName: /[A-Za-z_$][\w$.:-]*/y,
  operator: /=>|\.\.\.|\?\?=?|\?\.|[=!]==?|[<>]=?|&&|\|\||[-+*/%&|^~!?:;,.()[\]{}=<>@#]/y,
  jsxText: /[^<{]+/y,
  any: /[\s\S]/y,
};

function match(re: RegExp, src: string, at: number): string | null {
  re.lastIndex = at;
  const m = re.exec(src);
  return m && m[0].length > 0 ? m[0] : null;
}

// #region critical
/**
 * Split TSX source into coloured tokens. The mode stack is what lets one
 * regex pass tell `a < b` from `<Card>`: a `<` opens a tag only in
 * expression position (start, after a keyword, or after punctuation other
 * than `)`/`]`), and once inside a tag every bare identifier is an attribute.
 */
export function tokenizeTsx(src: string): Token[] {
  const out: Token[] = [];
  const stack: Mode[] = [{ kind: "code", braces: 0 }];
  let lastSignificant: Token | null = null;
  let i = 0;

  const push = (kind: TokenKind, text: string) => {
    const prev = out[out.length - 1];
    if (prev && prev.kind === kind) prev.text += text;
    else out.push({ kind, text });
    if (kind !== "comment" && text.trim() !== "") lastSignificant = { kind, text };
  };
  const top = () => stack[stack.length - 1] ?? { kind: "code" as const, braces: 0 };
  const inExpressionPosition = () => {
    const last: Token | null = lastSignificant;
    if (!last) return true;
    if (last.kind === "keyword") return true;
    return last.kind === "punct" && !/[)\]]$/.test(last.text);
  };
  const openTag = (closing: boolean) => {
    push("punct", closing ? "</" : "<");
    i += closing ? 2 : 1;
    const name = match(RE.tagName, src, i);
    if (name) {
      push("tag", name);
      i += name.length;
    }
    stack.push({ kind: "tag", closing });
  };

  while (i < src.length) {
    const mode = top();

    if (mode.kind === "text") {
      if (src.startsWith("</", i)) {
        if (src[i + 2] === ">") {
          // Fragment close `</>` ends this text run.
          push("punct", "</>");
          i += 3;
          stack.pop();
        } else openTag(true);
        continue;
      }
      if (src[i] === "<") {
        if (src[i + 1] === ">") {
          push("punct", "<>");
          i += 2;
          stack.push({ kind: "text" });
        } else openTag(false);
        continue;
      }
      if (src[i] === "{") {
        push("punct", "{");
        i += 1;
        stack.push({ kind: "code", braces: 0 });
        continue;
      }
      const text = match(RE.jsxText, src, i) ?? src.charAt(i);
      out.push({ kind: "plain", text });
      i += text.length;
      continue;
    }

    const space = match(RE.space, src, i);
    if (space) {
      out.push({ kind: "plain", text: space });
      i += space.length;
      continue;
    }
    const comment = match(RE.lineComment, src, i) ?? match(RE.blockComment, src, i);
    if (comment) {
      push("comment", comment);
      i += comment.length;
      continue;
    }
    const str = match(RE.string, src, i);
    if (str) {
      push("string", str);
      i += str.length;
      continue;
    }

    if (mode.kind === "tag") {
      if (src.startsWith("/>", i)) {
        push("punct", "/>");
        i += 2;
        stack.pop();
        continue;
      }
      if (src[i] === ">") {
        push("punct", ">");
        i += 1;
        stack.pop();
        // A closing tag also ends the text run it closed; an opening tag starts one.
        if (mode.closing) {
          if (top().kind === "text") stack.pop();
        } else stack.push({ kind: "text" });
        continue;
      }
      if (src[i] === "{") {
        push("punct", "{");
        i += 1;
        stack.push({ kind: "code", braces: 0 });
        continue;
      }
      const attr = match(RE.tagName, src, i);
      if (attr) {
        push("attr", attr);
        i += attr.length;
        continue;
      }
    } else {
      if (src[i] === "<" && inExpressionPosition()) {
        if (src[i + 1] === ">") {
          push("punct", "<>");
          i += 2;
          stack.push({ kind: "text" });
          continue;
        }
        if (/[A-Za-z_$]/.test(src[i + 1] ?? "")) {
          openTag(false);
          continue;
        }
      }
      if (src[i] === "{") {
        mode.braces += 1;
      } else if (src[i] === "}") {
        if (mode.braces > 0) mode.braces -= 1;
        else if (stack.length > 1) {
          push("punct", "}");
          i += 1;
          stack.pop();
          continue;
        }
      }
      const num = match(RE.number, src, i);
      if (num) {
        push("number", num);
        i += num.length;
        continue;
      }
      const ident = match(RE.ident, src, i);
      if (ident) {
        const next = src.slice(i + ident.length).match(/^\s*(\(|<[A-Za-z_$][\w$]*>\()/);
        const kind: TokenKind = KEYWORDS.has(ident)
          ? "keyword"
          : LITERALS.has(ident)
            ? "number"
            : next
              ? "function"
              : "plain";
        push(kind, ident);
        i += ident.length;
        continue;
      }
    }

    const op = match(RE.operator, src, i) ?? match(RE.any, src, i) ?? src.charAt(i);
    push("punct", op);
    i += op.length;
  }

  return out;
}
// #endregion

/**
 * Re-cut a token stream at newlines so each line can be rendered as its own
 * row (line numbers, highlighted lines). A multi-line comment or template
 * string keeps its colour on every line it spans.
 */
export function splitLines(tokens: Token[]): Token[][] {
  const lines: Token[][] = [[]];
  for (const token of tokens) {
    const parts = token.text.split("\n");
    parts.forEach((part, index) => {
      if (index > 0) lines.push([]);
      if (part) lines[lines.length - 1]?.push({ kind: token.kind, text: part });
    });
  }
  return lines;
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Code Block" (boardui.com/components/line-chart-card).
 * No BoardUI source was used.
 */
"use client";

import { RiCheckLine, RiFileCopyLine } from "@remixicon/react";
import { useCallback, useEffect, useRef, useState } from "react";
import type { ButtonHTMLAttributes, Ref } from "react";

import { cx } from "@/lib/cx";

/**
 * Write text to the clipboard. Uses the async Clipboard API when the page is
 * allowed to, and falls back to a hidden textarea + `execCommand("copy")` for
 * insecure origins, embedded iframes and browsers that reject the permission.
 * Resolves to whether the copy actually happened; it never throws.
 */
export async function writeClipboard(text: string): Promise<boolean> {
  try {
    if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    // Permission denied or not focused: fall through to the legacy path.
  }
  if (typeof document === "undefined") return false;
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.opacity = "0";
  area.style.pointerEvents = "none";
  document.body.appendChild(area);
  const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  area.select();
  let ok = false;
  try {
    ok = document.execCommand("copy");
  } catch {
    ok = false;
  }
  area.remove();
  previous?.focus({ preventScroll: true });
  return ok;
}

/**
 * `copied` flips true after a successful copy and back to false after
 * `resetMs`. Copying again restarts the window; the timer is cleared on
 * unmount.
 */
export function useCopyToClipboard(resetMs = 1600) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  const copy = useCallback(
    async (text: string) => {
      const ok = await writeClipboard(text);
      if (timer.current) clearTimeout(timer.current);
      setCopied(ok);
      if (ok) timer.current = setTimeout(() => setCopied(false), resetMs);
      return ok;
    },
    [resetMs],
  );

  return { copied, copy };
}

export interface CopyButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value" | "onCopy" | "children"> {
  /** Text to copy, or a function that produces it at click time. */
  value: string | (() => string);
  /** Accessible name before copying. */
  label?: string;
  /** Accessible name and live-region message after copying. */
  copiedLabel?: string;
  /** How long the check mark stays, in ms. */
  resetMs?: number;
  onCopied?: (text: string) => void;
  ref?: Ref<HTMLButtonElement>;
}

/** 32px square icon button: copy glyph that cross-fades to a check once copied. */
export function CopyButton({
  value,
  label = "Copy code",
  copiedLabel = "Copied",
  resetMs = 1600,
  onCopied,
  className,
  onClick,
  ref,
  ...props
}: CopyButtonProps) {
  const { copied, copy } = useCopyToClipboard(resetMs);

  return (
    <button
      ref={ref}
      type="button"
      aria-label={copied ? copiedLabel : label}
      data-copied={copied || undefined}
      {...props}
      onClick={async (event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        const text = typeof value === "function" ? value() : value;
        if (await copy(text)) onCopied?.(text);
      }}
      className={cx(
        "relative inline-flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-lg",
        "text-foreground-icon-secondary transition-colors duration-150 ease-out",
        "hover:bg-background-secondary-hover hover:text-foreground-icon-primary",
        "outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
        className,
      )}
    >
      <RiFileCopyLine
        aria-hidden
        className={cx(
          "absolute size-[18px] transition-[opacity,transform] duration-200 ease-out motion-reduce:transition-none",
          copied ? "scale-50 opacity-0" : "scale-100 opacity-100",
        )}
      />
      <RiCheckLine
        aria-hidden
        className={cx(
          "absolute size-[18px] text-status-lime-text transition-[opacity,transform] duration-200 ease-out motion-reduce:transition-none",
          copied ? "scale-100 opacity-100" : "scale-50 opacity-0",
        )}
      />
      <span role="status" className="sr-only">
        {copied ? copiedLabel : ""}
      </span>
    </button>
  );
}
